"""Write corpus/REVISION-4.md (profile counts, admission change matrix, positive and negative controls) and
corpus/INVARIANT-COVERAGE.md (per invariant and profile: a positive and a violating case with expected financial,
attribution and admission states). Usage: rev4_summary.py <corpus_dir>"""
import collections, glob, json, os, sys

corpus = sys.argv[1]
cs = {json.load(open(p))['case_id']: json.load(open(p)) for p in sorted(glob.glob(os.path.join(corpus, 'cases', '*.json')))}
def fd(c): return (c['evaluations'][0]['expected'].get('admission') or {}).get('decision')
def va(c): return c['role'] in ('valid_control', 'control') and fd(c) == 'admitted' and not any(a['blocking'] for a in c['expected']['attempts'])
L = ['# Corpus revision 4 (contract `1.3-s1`, P1.32)', '', 'Generated by `tools/rev4_summary.py`. Revisions 1 to 3 are preserved unchanged. '
     'Every revision-3 case is profile `current_producer`; every changed field is logged in `revisions_r4`, and `validate_corpus.py revisions` '
     'reconstructs revision 3 exactly. Historical blocks: 121/121 unchanged, and 128/128 current-producer cases reproduce byte-identically '
     'under a gated A1.3.4 rerun. Future-gated cases carry no historical comparison.', '', '## Profiles', '',
     '| Profile | Cases | Evaluations: admitted / refused / not established | Admitted valid controls | Metered admitted controls |', '|---|---|---|---|---|']
for prof in ('current_producer', 'future_qualified_gate'):
    sub = [c for c in cs.values() if c['profile'] == prof]
    d = collections.Counter(e['expected']['admission']['decision'] for c in sub for e in c['evaluations'] if e['expected'].get('admission'))
    v = [c for c in sub if va(c)]; m = [c for c in v if any(a['exposure'].get('pool') == 'pi_api' for a in c['expected']['attempts'])]
    L.append(f'| {prof} | {len(sub)} | {d["admitted"]} / {d["refused"]} / {d["not_established"]} | {len(v)} | {len(m)} |')
L += ['', '**Consequence stated plainly (OQ-1).** Under release `92a03789` no objective that has admitted a metered session can establish a new '
      'admission: every such session keeps an `AtLeast` commitment because a retired Pi session can resume without admission. The four current-producer '
      'admitted controls involve no admitted metered session (Codex or sessionless). Metered positive controls exist only in the future profile, '
      'with explicit gate evidence, and are not producer-reachable today.', '']
r3 = [c for c in cs.values() if c.get('revisions_r4')]
chg = [(c['case_id'], r) for c in r3 for r in c['revisions_r4'] if r['field'].endswith('admission.decision')]
L += [f'## Admission changes on revision-3 cases ({len(chg)})', '', '| Transition | Count | Rule |', '|---|---|---|']
for (f, t), n in sorted(collections.Counter((r['from'], r['to']) for _, r in chg).items()):
    rules = sorted({r['rule'].split(':')[0] for _, r in chg if (r['from'], r['to']) == (f, t)})
    L.append(f'| {f} → {t} | {n} | {"; ".join(rules)} |')
L += ['', '| Case | Evaluation | Revision 3 | Revision 4 | Rule |', '|---|---|---|---|---|']
for cid, r in chg: L.append(f'| `{cid}` | {r["field"].split("/")[0]} | {r["from"]} | {r["to"]} | {r["rule"].split(":")[0]} |')
L += ['', '**Derivation.** `refused` by OQ-2: the known total (owned high lines, known parts of `AtLeast`, every non-invalid commitment including the '
      '`retired_resumable` remainder `max(0, cap − owned high)`, the predecessor line and the request) exceeds the limit. Most corpus objectives have a limit '
      'equal to the session cap, so a resumable session plus any request exceeds it. `not_established` by OQ-4: a claimed closure (`closed_at`) without a '
      'consistent `scope_budget close` entry (D1-closed, U04 pair), or a known total within the limit with unresolved exposure (P130-R04-retired).', '']
new = [c for c in cs.values() if c.get('added_in') == '1.3-s1']
L += [f'## Added cases ({len(new)})', '', '| Case | Profile | Role | Admission |', '|---|---|---|---|']
for c in new: L.append(f'| `{c["case_id"]}` | {c["profile"]} | {c["role"]} | {"; ".join(e["name"] + ": " + e["expected"]["admission"]["decision"] for e in c["evaluations"])} |')
open(os.path.join(corpus, 'REVISION-4.md'), 'w').write('\n'.join(L) + '\n')

def state(c):
    e = c['evaluations'][0]; ee = e['expected']
    fin = '; '.join(f'{a["exposure"]["high"]["kind"]}({a["exposure"]["high"]["nano"]})' if a['exposure'].get('pool') == 'pi_api' else 'codex' for a in c['expected']['attempts']) or 'no attempt'
    att = '; '.join(f'{x["ownership"]}/{x["placement"]}' for x in ee['attribution']) or 'none'
    com = '; '.join(f'{cm["state"]}:{cm["kind"]}' for o in ee['objectives'] for cm in o['commitments']) or 'none'
    return f'{fin} / {att} / {com} / {(ee.get("admission") or {}).get("decision")}'
INV = sorted({i for c in cs.values() for i in c['invariants']}, key=lambda x: (x[4], int(x[5:])))
ALT = {'INV-A1': 'self-test `always_reject` (fails in both profiles)', 'INV-F8': 'sabotage `twin differs`', 'INV-F10': 'harness: two runs byte for byte',
       'INV-T5': '`N03-identity-refusal-in-subscription` (lane contradicted)'}
M = ['# Invariant coverage (contract `1.3-s1`)', '', 'Generated by `tools/rev4_summary.py`. Per invariant: a positive case (satisfies it) and a violating case '
     '(a finding whose naive treatment violates it), each with expected attempt highs / attribution / commitments / admission (first evaluation), and the profile.', '',
     '| Invariant | Positive (profile) | state | Violating (profile) | state |', '|---|---|---|---|---|']
missing = []
for inv in INV:
    pos = [c for c in cs.values() if inv in c['invariants'] and c['role'] in ('valid_control', 'control')]
    neg = [c for c in cs.values() if inv in c['invariants'] and c['role'] == 'finding']
    if not pos: pos = [cs[ctl] for c in neg for ctl in c['controls'] if ctl in cs][:1]
    p = pos[0] if pos else None; n = neg[0] if neg else None
    if not p or (not n and inv not in ALT): missing.append(inv)
    M.append(f'| {inv} | {("`" + p["case_id"] + "` (" + p["profile"] + ")") if p else "—"} | {state(p) if p else "—"} | '
             f'{("`" + n["case_id"] + "` (" + n["profile"] + ")") if n else ALT.get(inv, "—")} | {state(n) if n else "—"} |')
M += ['', f'Invariants without a positive case, or without a violating case or stated violation route: {missing or "none"}.']
open(os.path.join(corpus, 'INVARIANT-COVERAGE.md'), 'w').write('\n'.join(M) + '\n')
print(f'{len(chg)} admission changes on rev-3 cases; {len(new)} added; invariants missing a pair: {missing}')
